    pub const fn name(self) -> &'static str { Self::NAMES[self as usize] }
    pub fn from_name(name: &str) -> Option<InternalErrorKind> { Self::ALL.into_iter().find(|member| member.name() == name) }
    pub const fn to_wire(self) -> u32 { self as u32 }
    pub const fn from_wire(word: u32) -> Option<InternalErrorKind> { if (word as usize) < Self::COUNT { Some(Self::ALL[word as usize]) } else { None } }
    pub const fn stage(self) -> Stage { Self::STAGE[self as usize] }
    pub const fn message(self) -> &'static str { Self::MESSAGE[self as usize] }
